//____________________________________________SAVE_____________________________________________\\
@Override
public SuccessRes saveRawBuildingDetails(RawBuildingsDetailsSaveReq req) {
	SuccessRes res = new SuccessRes();
	DozerBeanMapper mapper = new DozerBeanMapper();
	try {
		Long newId =0L;
		RawBuildingsDetails ent = new RawBuildingsDetails();

		ent = mapper.map(req, RawBuildingsDetails.class);
		newId = buildingRepo.count()+10001;
		ent.setRequestReferenceNo(newId.toString());
		ent.setEntryDate(new Date());
		ent.setStatus("Y");
		ent.setUpdatedBy(req.getCreatedBy());
		ent.setUpdatedDate(new Date());
		res.setSuccessId(newId.toString());
		res.setResponse("Inserted Successfully");

		buildingRepo.save(ent);
		
			
	} catch (Exception e) {
		e.printStackTrace();
		log.info("Log Details" + e.getMessage());
		return null;
	}
	return res;

}

//____________________________________________GET_____________________________________________\\
@Override
public RawBuildingsDetailsRes getBuildingDetails(RawBuildingDetailsGetReq req) {
	RawBuildingsDetailsRes res = new RawBuildingsDetailsRes();
	DozerBeanMapper mapper = new DozerBeanMapper();
	try {
		RawBuildingsDetails data = buildingRepo.findByRequestReferenceNo(Integer.valueOf(req.getRequestReferenceNo()));
		res = mapper.map(data, RawBuildingsDetailsRes.class);
	} catch (Exception e) {
		e.printStackTrace();
		log.info("Log Details" + e.getMessage());
		return null;
	}
	return res;
}

